def reciprocal_rank(ranked_sources, expected_source):
    # Find the index of the expected source in the ranked list
    index = ranked_sources.index(expected_source) if expected_source in ranked_sources else -1

    # Calculate the reciprocal rank
    if index != -1:
        return 1 / (index + 1)
    else:
        return 0.0
